'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),T=32,W=56,H=36,keys=new Set(),dialog=$('#dialog');
const fresh=()=>({x:9*T,y:17*T,hp:100,level:1,xp:0,gold:0,potions:3,kills:0,quest:0,upgrade:0,boss:false});
let p=fresh(),saveOK=true;try{const s=JSON.parse(localStorage.getItem('moonwind-v1'));if(s&&Number.isFinite(s.x)&&s.level>=1&&s.level<=100&&s.hp>0)p={...p,...s};}catch{saveOK=false;}
let cam={x:0,y:0},time=0,last=0,attackCD=0,skillCD=0,slash=0,face=1,invuln=0,running=true,sound=false,audio=null,toastTimer,saveTimer=0;const effects=[],enemies=[];
const npcs=[{x:9*T,y:14*T,name:'이장 하람',color:'#ceb975',type:'quest'},{x:5*T,y:18*T,name:'약초상 연',color:'#bba2c5',type:'shop'},{x:13*T,y:18*T,name:'대장장이',color:'#c28b6b',type:'smith'}];
const trees=[];for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){if((x*17+y*31)%13===0&&!(x<18&&y>9&&y<24)&&!(y>=15&&y<=19)&&!(x>43&&y>10&&y<23))trees.push({x:x*T,y:y*T});}
function terrain(x,y){return x<1||y<1||x>W-2||y>H-2||(x>=19&&x<=22&&(y<15||y>19));}
function solid(x,y){if(terrain(x/T,y/T))return true;if(trees.some(t=>Math.abs(x-t.x)<17&&Math.abs(y-t.y)<13))return true;return buildings.some(b=>x>b.x-5&&x<b.x+b.w+5&&y>b.y+12&&y<b.y+b.h);}
const buildings=[{x:3*T,y:10*T,w:4*T,h:3*T},{x:11*T,y:10*T,w:4*T,h:3*T},{x:4*T,y:21*T,w:4*T,h:3*T},{x:12*T,y:21*T,w:4*T,h:3*T}];
function spawn(x,y,boss=false){enemies.push({x:x*T,y:y*T,homeX:x*T,homeY:y*T,hp:boss?250:32,max:boss?250:32,boss,dead:0,cd:0,phase:Math.random()*6});}
for(let i=0;i<12;i++)spawn(27+(i*7)%15,8+(i*5)%21);if(!p.boss)spawn(47,17,true);
function beep(f=440){if(!sound)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.15);}catch{}}
function notify(msg){$('#message').textContent=msg;$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function save(){try{localStorage.setItem('moonwind-v1',JSON.stringify(p));}catch{saveOK=false;}$('#save-status').textContent=saveOK?'진행 상황은 이 브라우저에 자동 저장됩니다.':'저장이 차단되어 있습니다. 현재 세션에서만 진행됩니다.';}
function maxHP(){return 100+(p.level-1)*20;}function atk(){return 12+(p.level-1)*3+p.upgrade*6;}
function ui(){$('#level').textContent=`Lv. ${p.level}`;$('#hptext').textContent=`${Math.ceil(p.hp)} / ${maxHP()}`;$('#hp').style.width=`${p.hp/maxHP()*100}%`;$('#xptext').textContent=`${p.xp} / ${p.level*40}`;$('#xp').style.width=`${p.xp/(p.level*40)*100}%`;$('#gold').textContent=`${p.gold} 냥`;$('#atk').textContent=atk();$('#pots').textContent=p.potions;$('#coords').textContent=p.x<19*T?'달빛 마을':p.x>43*T?'수호자의 공터':'안개 숲';$('#quest').textContent=['이장 하람에게 E 키로 말을 걸어보세요.','숲의 들깨비 5마리를 물리치고 하람에게 돌아가세요.','동쪽 공터의 안개 수호자를 물리치세요.','마을에 평화를 되찾았습니다. 자유롭게 탐험하세요.'][p.quest];$('#questprogress').textContent=p.quest===1?`들깨비 처치 ${Math.min(5,p.kills)} / 5`:p.quest===2?(p.boss?'수호자 처치 완료 · 하람에게 보고':'수호자 처치 0 / 1'):p.quest===3?'✦ 달빛 마을의 수호자':'';$('#skill').disabled=skillCD>0;}
function textFX(x,y,text,color='#ffe5a4'){effects.push({x,y,text,color,life:1});}
function gain(e){p.xp+=e.boss?100:15;p.gold+=e.boss?120:8;if(e.boss){p.boss=true;notify('안개가 걷혔습니다! 하람에게 돌아가세요.');}else p.kills++;while(p.xp>=p.level*40){p.xp-=p.level*40;p.level++;p.hp=maxHP();notify(`레벨 ${p.level}! 생명력이 회복되었습니다.`);beep(800);}save();}
function attack(skill=false){if(!running||dialog.open||attackCD>0||(skill&&skillCD>0))return;attackCD=skill?.55:.32;slash=skill?.35:.18;if(skill)skillCD=5;beep(skill?660:300);const range=skill?140:65;for(const e of enemies){if(e.dead||Math.hypot(e.x-p.x,e.y-p.y)>range)continue;const damage=atk()*(skill?2:1);e.hp-=damage;textFX(e.x,e.y-22,damage);if(e.hp<=0){e.dead=e.boss?Infinity:12;gain(e);}}ui();}
function potion(){if(p.potions<=0){notify('체력약이 없습니다. 약초상 연을 찾아가세요.');return;}if(p.hp>=maxHP()){notify('생명력이 가득 차 있습니다.');return;}p.potions--;p.hp=Math.min(maxHP(),p.hp+65);beep(560);notify('체력약으로 생명력 65 회복');save();ui();}
function openDialog(who,title,text,choices=[]){$('#speaker').textContent=who;$('#dialogtitle').textContent=title;$('#dialogtext').textContent=text;$('#choices').replaceChildren();for(const [label,fn]of choices){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();ui();save();};$('#choices').append(b);}keys.clear();dialog.showModal();}
function interact(){const n=npcs.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<80);if(!n){notify('주민 가까이에서 E를 눌러 대화하세요.');return;}if(n.type==='shop')openDialog(n.name,'숲에 가기 전, 든든하게','체력약은 생명력을 65 회복합니다. 한 병에 12냥이에요.',[['체력약 구매 · 12냥',()=>{if(p.gold<12){notify('소지금이 부족합니다.');return;}p.gold-=12;p.potions++;notify('체력약을 구매했습니다.');}]]);else if(n.type==='smith')openDialog(n.name,'검에도 이야기가 쌓이지','40냥이면 공격력을 6 높여주겠네.',[['검 강화 · 40냥',()=>{if(p.gold<40){notify('소지금이 부족합니다.');return;}p.gold-=40;p.upgrade++;notify('검 강화 완료! 공격력 +6');}]]);else if(p.quest===0)openDialog(n.name,'안개 숲의 소문','동쪽 숲에 들깨비가 나타났네. 5마리를 물리쳐주겠나? 보상은 50냥과 체력약 2병이네.',[['의뢰 수락',()=>{p.quest=1;dialog.close();notify('의뢰 수락: 들깨비 5마리 처치');}]]);else if(p.quest===1&&p.kills>=5)openDialog(n.name,'고맙네, 여행자','50냥과 체력약 2병을 받게. 이제 동쪽 끝 공터의 안개 수호자를 쓰러뜨려주게.',[['보상 받기',()=>{p.gold+=50;p.potions+=2;p.quest=2;dialog.close();notify('새 의뢰: 안개 수호자');}]]);else if(p.quest===2&&p.boss)openDialog(n.name,'달빛 마을의 수호자','마을에 평화를 돌려주었네. 자네의 이야기는 오래도록 기억될 걸세. 보상 200냥을 받게.',[['모험 완수 · 200냥',()=>{p.gold+=200;p.quest=3;dialog.close();notify('모험 완수! 달빛 마을의 수호자가 되었습니다.');}]]);else openDialog(n.name,'바람이 자네를 이끌기를',p.quest===3?'언제든 쉬어가게. 마을은 자네를 환영한다네.':'아직 숲에 안개가 남아 있네. 준비를 마치고 동쪽으로 가보게.');}
