function update(dt){if(dialog.open||!running)return;time+=dt;attackCD=Math.max(0,attackCD-dt);skillCD=Math.max(0,skillCD-dt);slash=Math.max(0,slash-dt);invuln=Math.max(0,invuln-dt);let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);if(dx||dy){const norm=Math.hypot(dx,dy);move(p,dx/norm*145*dt,dy/norm*145*dt);if(dx)face=dx;}if(keys.has(' '))attack();if(p.x<18*T)p.hp=Math.min(maxHP(),p.hp+6*dt);for(const e of enemies){if(e.dead){if(e.dead!==Infinity){e.dead-=dt;if(e.dead<=0){e.dead=0;e.hp=e.max;e.x=e.homeX;e.y=e.homeY;}}continue;}e.cd-=dt;const d=Math.hypot(p.x-e.x,p.y-e.y);if(d<230&&p.x>23*T){if(d>25)move(e,(p.x-e.x)/d*(e.boss?55:65)*dt,(p.y-e.y)/d*(e.boss?55:65)*dt);if(d<38&&e.cd<=0&&invuln<=0){const damage=e.boss?22:8;p.hp-=damage;e.cd=1;invuln=.4;textFX(p.x,p.y-30,'−'+damage,'#ffa39a');beep(130);if(p.hp<=0){p.x=9*T;p.y=17*T;p.hp=maxHP();p.gold=Math.max(0,p.gold-15);notify('마을에서 부활했습니다. 치료비 15냥');save();}}}}for(const f of effects){f.life-=dt;f.y-=dt*26;}while(effects.length&&effects[0].life<=0)effects.shift();saveTimer+=dt;if(saveTimer>3){saveTimer=0;save();}ui();}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}function label(t,x,y,color='#edf0d0'){ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#0d211cd9';ctx.fillRect(x-ctx.measureText(t).width/2-5,y-12,ctx.measureText(t).width+10,17);ctx.fillStyle=color;ctx.fillText(t,x,y);}
