function tree(t){const {x,y}=t;rect(x-3,y-3,7,21,'#695542');rect(x-17,y-23,34,27,'#203f32');rect(x-13,y-35,26,26,'#315a3f');rect(x-8,y-41,17,21,'#446847');rect(x-11,y-28,5,6,'#648257');rect(x+8,y-13,5,6,'#436b46');}
function draw(){cam.x=Math.max(0,Math.min(W*T-960,p.x-480));cam.y=Math.max(0,Math.min(H*T-600,p.y-300));ctx.imageSmoothingEnabled=false;ctx.save();ctx.translate(-Math.floor(cam.x),-Math.floor(cam.y));rect(0,0,W*T,H*T,'#4c6945');for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(x*T<cam.x-40||x*T>cam.x+1000||y*T<cam.y-40||y*T>cam.y+640)continue;const hash=(x*37+y*23)%19;rect(x*T,y*T,32,32,hash<6?'#506e49':'#4c6945');if(hash<8){rect(x*T+5,y*T+13,2,4,'#73925b');rect(x*T+8,y*T+11,2,6,'#73925b');}if(y>=15&&y<=19){rect(x*T,y*T,32,32,'#aa986b');rect(x*T+hash,y*T+hash,4,2,'#91845e');}if(x>=19&&x<=22&&(y<15||y>19)){rect(x*T,y*T,32,32,'#426f70');rect(x*T+2,y*T+((time*8+y*7)%30),18,2,'#719794');}if(x<1||y<1||x>W-2||y>H-2)rect(x*T,y*T,32,32,'#2d4c35');}rect(19*T,15*T,4*T,5*T,'#886e4a');for(let i=0;i<16;i++)rect(19*T,15*T+i*10,4*T,2,'#624f39');rect(19*T,15*T,4*T,5,'#bcaa76');rect(19*T,20*T-5,4*T,5,'#bcaa76');for(const b of buildings){rect(b.x,b.y+20,b.w,b.h-20,'#d0b887');rect(b.x+8,b.y+35,b.w-16,4,'#947954');rect(b.x+b.w/2-10,b.y+b.h-35,21,35,'#4a4a37');rect(b.x-7,b.y,b.w+14,30,'#3a5554');for(let j=0;j<b.w;j+=12)rect(b.x+j,b.y+5,2,23,'#638078');rect(b.x-12,b.y+27,b.w+24,6,'#283f40');rect(b.x+10,b.y+49,20,17,'#796c46');}label('달빛 마을',9*T,9*T,'#ead5a3');label('안개 숲 →',27*T,15*T-20,'#d2deab');label('수호자의 공터',47*T,12*T,'#e4ce93');const entities=[...trees.map(t=>({y:t.y,draw:()=>tree(t)})),...npcs.map(n=>({y:n.y,draw:()=>{person(n.x,n.y,n.color);label(n.name,n.x,n.y-40);if(Math.hypot(n.x-p.x,n.y-p.y)<80)label('E · 대화',n.x,n.y+32,'#f7dba0');}})),...enemies.filter(e=>!e.dead).map(e=>({y:e.y,draw:()=>{const size=e.boss?25:13;ctx.fillStyle='#15271966';ctx.beginPath();ctx.ellipse(e.x,e.y+9,size,6,0,0,7);ctx.fill();rect(e.x-size,e.y-size,size*2,size*1.6,e.boss?'#747b9a':'#a89065');rect(e.x-size+4,e.y-size-6,6,9,e.boss?'#a4aac2':'#d2b47b');rect(e.x+size-10,e.y-size-6,6,9,e.boss?'#a4aac2':'#d2b47b');rect(e.x-7,e.y-8,3,4,'#1b2928');rect(e.x+5,e.y-8,3,4,'#1b2928');if(e.hp<e.max){rect(e.x-size,e.y-size-15,size*2,3,'#253a2e');rect(e.x-size,e.y-size-15,size*2*e.hp/e.max,3,'#d59579');}if(e.boss)label('안개 수호자',e.x,e.y-47,'#eed9b1');}})),{y:p.y,draw:()=>{if(invuln<=0||Math.floor(time*20)%2===0)person(p.x,p.y,'#779db0',true);label('여행자',p.x,p.y-43,'#e7deba');}}];entities.sort((a,b)=>a.y-b.y);entities.forEach(e=>e.draw());if(slash>0){ctx.strokeStyle=skillCD>4.6?'#d9efc1':'#ffe8b3';ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y-5,skillCD>4.6?120:48,-1.3,2.3);ctx.stroke();}for(const f of effects){ctx.globalAlpha=Math.max(0,f.life);ctx.fillStyle=f.color;ctx.font='bold 16px system-ui';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y);}ctx.globalAlpha=1;ctx.restore();const vignette=ctx.createRadialGradient(480,300,150,480,300,590);vignette.addColorStop(0,'#0b211000');vignette.addColorStop(1,'#081c2344');ctx.fillStyle=vignette;ctx.fillRect(0,0,960,600);}
function loop(ts){const dt=Math.min((ts-last)/1000,.05);last=ts;update(dt);draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
window.addEventListener('keydown',e=>{if(dialog.open)return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(e.key.startsWith('Arrow')?e.key:k);if(e.repeat)return;if(k==='q')attack(true);if(k==='e')interact();if(k==='1')potion();});window.addEventListener('keyup',e=>keys.delete(e.key.startsWith('Arrow')?e.key:e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();save();});document.addEventListener('visibilitychange',()=>{keys.clear();running=!document.hidden;last=performance.now();});$('#close').onclick=()=>dialog.close();$('#potion').onclick=potion;$('#skill').onclick=()=>attack(true);$('#help').onclick=()=>openDialog('여행자의 안내서','작은 모험을 시작하세요','WASD 또는 방향키로 이동 · 스페이스로 주변의 적 공격 · Q 달빛베기 (재사용 5초) · E 주민과 대화 · 1 체력약. 마을에서는 생명력이 회복됩니다. 하람의 의뢰를 받은 뒤 동쪽 다리를 건너세요. 모바일은 화면 아래 버튼을 사용하세요.');$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'소리 끄기':'소리 켜기';beep();};$('#reset').onclick=()=>openDialog('새로운 여정','처음부터 다시 시작할까요?','현재 브라우저의 저장된 진행 상황이 초기화됩니다.',[['새 모험 시작',()=>{p=fresh();enemies.length=0;for(let i=0;i<12;i++)spawn(27+(i*7)%15,8+(i*5)%21);spawn(47,17,true);skillCD=0;attackCD=0;dialog.close();save();notify('새로운 모험이 시작됩니다.');}]]);for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key));}for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>({attack:()=>attack(),skill:()=>attack(true),interact})[b.dataset.action]();ui();save();
